INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Primärschlüssel immer eine einzelne Spalte?', 2, '[{"text": "Nein", "correct": true, "because": "Kann aus mehreren Spalten bestehen"}, {"text": "Ja", "correct": false, "because": "Verbundschlüssel möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines Primärschlüssels?', 3, '[{"text": "Eindeutige Identifikation", "correct": true, "because": "Verhindert Duplikate"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht primäre Funktion"}, {"text": "Manuelle Zuweisung", "correct": false, "because": "Automatisch besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein Primärschlüssel?', 5, '[{"text": "Eindeutigkeit", "correct": true, "because": "Kein Wert doppelt"}, {"text": "Nicht-Null", "correct": true, "because": "NULL nicht erlaubt"}, {"text": "Änderbarkeit", "correct": false, "because": "Soll stabil sein"}, {"text": "Optionale Werte", "correct": false, "because": "Pflichtfeld"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Primärschlüssel verhindert Duplikate. b) Er muss immer numerisch sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann auch Text sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Primärschlüssels?', 4, '[{"text": "Eindeutigkeit", "correct": false, "because": "Kernanforderung"}, {"text": "Stabilität", "correct": false, "because": "Verhindert spätere Änderungen"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Schlüssel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Primärschlüssel NULL-Werte enthalten darf?', 2, '[{"text": "Nein", "correct": true, "because": "NULL ist nicht eindeutig"}, {"text": "Ja", "correct": false, "because": "Verstößt gegen Regel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Datentyp ist für einen Primärschlüssel typisch?', 3, '[{"text": "Integer", "correct": true, "because": "Einfach und effizient"}, {"text": "Bilddatei", "correct": false, "because": "Ungeeignet für Schlüssel"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Nicht automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt ein Primärschlüssel?', 5, '[{"text": "Eindeutige Identifikation", "correct": true, "because": "Sichert Datensatz"}, {"text": "Verknüpfung von Tabellen", "correct": true, "because": "Fremdschlüssel nutzt ihn"}, {"text": "Datenkompression", "correct": false, "because": "Keine Schlüsselaufgabe"}, {"text": "Grafische Darstellung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Primärschlüssel kann aus mehreren Spalten bestehen. b) Er muss immer automatisch generiert sein. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Primärschlüssel?', 4, '[{"text": "Eindeutigkeit", "correct": false, "because": "Kernmerkmal"}, {"text": "Indexierung", "correct": false, "because": "Verbessert Suche"}, {"text": "Variable Werte", "correct": true, "because": "Stabilität wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Primärschlüssel dasselbe wie ein Fremdschlüssel?', 2, '[{"text": "Nein", "correct": true, "because": "Fremdschlüssel verweist auf Primärschlüssel"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Rollen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkungen hat ein Primärschlüssel?', 4, '[{"text": "Keine NULL-Werte", "correct": true, "because": "Pflichtfeld"}, {"text": "Eindeutigkeit", "correct": true, "because": "Verhindert Duplikate"}, {"text": "Beliebige Änderung", "correct": false, "because": "Soll stabil sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Primärschlüssel immer numerisch sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch Text sein"}, {"text": "Ja", "correct": false, "because": "Datentyp flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines Primärschlüssels?', 3, '[{"text": "Einfachheit", "correct": true, "because": "Erleichtert Verwaltung"}, {"text": "Komplexe Werte", "correct": false, "because": "Erschweren Zugriff"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Primärschlüssel sind eindeutig. b) Sie müssen aus Text bestehen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Primärschlüssel?', 5, '[{"text": "Datenintegrität", "correct": true, "because": "Verhindert Duplikate"}, {"text": "Effiziente Suche", "correct": true, "because": "Indexierung unterstützt"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Manuelle Änderung", "correct": false, "because": "Stabilität wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Primärschlüssel unwichtig?', 3, '[{"text": "Eindeutigkeit", "correct": false, "because": "Kernanforderung"}, {"text": "Nicht-Null-Eigenschaft", "correct": false, "because": "Pflicht"}, {"text": "Grafische Darstellung", "correct": true, "because": "Kein Schlüsselmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Primärschlüssel geändert werden sollte?', 2, '[{"text": "Nein", "correct": true, "because": "Änderungen stören Verknüpfungen"}, {"text": "Ja", "correct": false, "because": "Stabilität entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Tabelle mehrere Primärschlüssel haben?', 3, '[{"text": "Nein", "correct": true, "because": "Nur ein Primärschlüssel pro Tabelle"}, {"text": "Ja", "correct": false, "because": "Einzigartigkeit nur einmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Primärschlüssel?', 4, '[{"text": "Eindeutige Kunden-ID in Datenbank", "correct": true, "because": "Identifiziert Datensätze"}, {"text": "Bildbearbeitung", "correct": false, "because": "Keine Datenbankaufgabe"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Schlüsselkontext"}]');
